import{_ as n,o as r,c as i,ah as t}from"./chunks/framework.Bja9t6Wf.js";const m=JSON.parse('{"title":"Recherche: Der Fall Christian Pilnacek","description":"","frontmatter":{},"headers":[],"relativePath":"recherche/der-fall-pilnacek.md","filePath":"recherche/der-fall-pilnacek.md"}'),s={name:"recherche/der-fall-pilnacek.md"};function a(h,e,l,u,o,c){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="recherche-der-fall-christian-pilnacek" tabindex="-1">Recherche: Der Fall Christian Pilnacek <a class="header-anchor" href="#recherche-der-fall-christian-pilnacek" aria-label="Permalink to &quot;Recherche: Der Fall Christian Pilnacek&quot;">​</a></h1><p><strong>Die geheimen Tonaufnahmen und das „Abdrehen“ von Ermittlungen.</strong></p><p>Christian Pilnacek war über ein Jahrzehnt der mächtigste Beamte im österreichischen Justizministerium. Sein Fall und der dazugehörige Untersuchungsausschuss (2025–2026) bilden die dunkle Schnittstelle zwischen Politik und Justiz in unserer Mockumentary.</p><hr><h2 id="die-schlusselelemente" tabindex="-1">Die Schlüsselelemente <a class="header-anchor" href="#die-schlusselelemente" aria-label="Permalink to &quot;Die Schlüsselelemente&quot;">​</a></h2><h3 id="_1-die-geheimen-tonaufnahmen-november-2023" tabindex="-1">1. Die geheimen Tonaufnahmen (November 2023) <a class="header-anchor" href="#_1-die-geheimen-tonaufnahmen-november-2023" aria-label="Permalink to &quot;1. Die geheimen Tonaufnahmen (November 2023)&quot;">​</a></h3><p>Kurz nach seinem Tod im Oktober 2023 wurden Tonmitschnitte publik, die Pilnacek heimlich bei einem Treffen in einem Wiener Lokal aufgenommen hatten. Darin erhebt er schwere Vorwürfe gegen die ÖVP:</p><ul><li><strong>Die Sobotka-Intervention:</strong> Pilnacek behauptet, Wolfgang Sobotka habe ihn gefragt, warum er Ermittlungen nicht „abdrehe“.</li><li><strong>Politischer Druck:</strong> Er beschreibt, wie die Volkspartei über Jahre versucht habe, Verfahren gegen ihre Exponenten zu beeinflussen.</li></ul><h3 id="_2-der-untersuchungsausschuss-2025–2026" tabindex="-1">2. Der Untersuchungsausschuss (2025–2026) <a class="header-anchor" href="#_2-der-untersuchungsausschuss-2025–2026" aria-label="Permalink to &quot;2. Der Untersuchungsausschuss (2025–2026)&quot;">​</a></h3><p>Seit November 2025 befasst sich ein eigener U-Ausschuss mit den Vorwürfen des Machtmissbrauchs.</p><ul><li><strong>Zentrale Themen:</strong> Politische Einflussnahme auf Ermittlungen, die Auswertung von Pilnaceks Smartwatch-Daten und die Umstände seines Todes.</li><li><strong>Befund der Kreutner-Kommission:</strong> Eine begleitende Kommission unter Martin Kreutner stellte 2024 eine „hochproblematische Zwei-Klassen-Justiz“ in Österreich fest.</li></ul><hr><h2 id="bedeutung-fur-das-„horten-mysterium" tabindex="-1">Bedeutung für das „Horten-Mysterium“ <a class="header-anchor" href="#bedeutung-fur-das-„horten-mysterium" aria-label="Permalink to &quot;Bedeutung für das „Horten-Mysterium“&quot;">​</a></h2><p>Der Fall Pilnacek ist für unser Projekt die moderne Entsprechung des „Archivs des Schweigens“.</p><ul><li><strong>Das Motiv des „Abdrehens“:</strong> Während wir in der Horten-Ära zeigen, wie Namen von Gebäuden gelöscht wurden, zeigen wir in der Ära Pilnacek, wie versucht wurde, ganze Ermittlungsstränge aus den Akten zu tilgen.</li><li><strong>Juristischer Pointillismus:</strong> Ein System, in dem nicht ein großes Gesetz gebrochen wird, sondern viele kleine Interventionen, Telefonate und informelle Treffen (wie in der Tonaufnahme) das Gesamtbild der Rechtsstaatlichkeit verzerren.</li></ul><hr><h2 id="medien-link-„das-politische-testament" tabindex="-1">Medien-Link: „Das politische Testament“ <a class="header-anchor" href="#medien-link-„das-politische-testament" aria-label="Permalink to &quot;Medien-Link: „Das politische Testament“&quot;">​</a></h2><p>In unserer Sektion <a href="/medien.html">Geheime Medien</a> finden Sie die (nachgestellten) Transkripte der Pilnacek-Aufnahmen, die als atmosphärischer Leitfaden für Teil 4 unseres Drehbuchs dienen.</p><hr><p><em>Quellen: Protokolle des Pilnacek-Untersuchungsausschusses (2026), Bericht der Kreutner-Kommission (2024), Berichterstattung von Standard, ORF und Profil.</em></p>',20)])])}const g=n(s,[["render",a]]);export{m as __pageData,g as default};
